-- Re-runnable: subtopic-scoped DELETE. Run the four batches in any order in the Supabase SQL editor.
BEGIN;
DELETE FROM questions WHERE topic = 'Oxidation-Reduction Reactions' AND subtopic IN ('Disproportionation Reactions', 'Net Ionic Equations & Spectator Ions');

-- Q1 [Disproportionation Reactions · easy · Skill 1 · 4E Stoichiometry (GC) · ans D] (g48)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Disproportionation Reactions',
    $qt48$Copper(I) ion is unstable in aqueous solution and reacts with itself according to the balanced equation \(2\,\text{Cu}^+(aq) \rightarrow \text{Cu}(s) + \text{Cu}^{2+}(aq)\). This reaction is classified as a disproportionation. Which statement best identifies the feature of this reaction that makes it a disproportionation?$qt48$,
    $op48$[{"label":"A","text":"Copper acts only as a spectator ion and its oxidation state remains +1 throughout the reaction."},{"label":"B","text":"Two different elements exchange electrons, with copper being oxidized while a separate element is reduced."},{"label":"C","text":"Copper is reduced from +2 to +1 while no atom in the reaction is oxidized."},{"label":"D","text":"A single element, copper, begins in one oxidation state (+1) and is simultaneously oxidized to +2 and reduced to 0."}]$op48$::jsonb,
    'D',
    $ex48$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is D because disproportionation is defined as a reaction in which a single element in one oxidation state is simultaneously oxidized and reduced. Tracking copper's oxidation number: on the left, both copper atoms are \(\text{Cu}^+\), so each copper starts at +1. On the right, one product is \(\text{Cu}(s)\), elemental copper with oxidation number 0, and the other product is \(\text{Cu}^{2+}\) with oxidation number +2. One copper atom is reduced (\(+1 \rightarrow 0\), gaining one electron) and the other copper atom is oxidized (\(+1 \rightarrow +2\), losing one electron). The single electron lost by the oxidized copper exactly balances the single electron gained by the reduced copper, and the charge balances as well: the left side is \(2(+1) = +2\) and the right side is \(0 + (+2) = +2\). Because the very same element (copper) starting from the same oxidation state is both oxidized and reduced, the reaction is a disproportionation. (Choice A) This is false because copper does not keep a constant +1 oxidation state and is not a spectator; copper is the species whose oxidation number changes, which is precisely why a redox classification applies. (Choice B) This describes an ordinary redox reaction between two different elements, which is the opposite of disproportionation; in this reaction only one element, copper, changes oxidation state. (Choice C) This reverses the direction of the change: copper is not reduced from +2 to +1, and it is incorrect that no atom is oxidized, since one copper atom is in fact oxidized from +1 to +2. Skill 1$ex48$,
    'easy', '4E', $cc48$Stoichiometry (GC)$cc48$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a48A$Misidentifies copper as an unchanging spectator ion rather than the species being oxidized and reduced$a48A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a48B$Describes a standard two-element redox instead of one element undergoing both oxidation and reduction$a48B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a48C$Reverses copper's oxidation-state change and denies that any oxidation occurs$a48C$ FROM q;

-- Q2 [Disproportionation Reactions · easy · Skill 1 · 4E Stoichiometry (GC) · ans A] (g49)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Disproportionation Reactions',
    $qt49$When nitrogen dioxide is bubbled through water, it reacts according to the balanced equation \(3\,\text{NO}_2 + \text{H}_2\text{O} \rightarrow 2\,\text{HNO}_3 + \text{NO}\). This is classified as a disproportionation reaction, in which a single element is simultaneously oxidized and reduced. Which element disproportionates, and what are the two oxidation states it reaches in the two products?$qt49$,
    $op49$[{"label":"A","text":"Nitrogen, which is oxidized to \\(+5\\) in \\(\\text{HNO}_3\\) and reduced to \\(+2\\) in \\(\\text{NO}\\)."},{"label":"B","text":"Oxygen, which is oxidized to \\(0\\) in \\(\\text{NO}\\) and reduced to \\(-2\\) in \\(\\text{HNO}_3\\)."},{"label":"C","text":"Hydrogen, which is oxidized to \\(+1\\) in \\(\\text{HNO}_3\\) and reduced to \\(0\\) elsewhere."},{"label":"D","text":"Nitrogen, which is oxidized to \\(+6\\) in \\(\\text{HNO}_3\\) and reduced to \\(0\\) in \\(\\text{NO}\\)."}]$op49$::jsonb,
    'A',
    $ex49$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is A because nitrogen is the only element whose oxidation state changes, and it changes in two opposite directions from a single starting value. In the reactant \(\text{NO}_2\), each oxygen is \(-2\), so the two oxygens contribute \(-4\); for the neutral molecule, nitrogen must be \(+4\). In \(\text{HNO}_3\), hydrogen is \(+1\) and the three oxygens total \(-6\); to give a neutral molecule, nitrogen must be \(+5\), so this nitrogen is oxidized (\(+4 \rightarrow +5\)). In \(\text{NO}\), oxygen is \(-2\), so nitrogen must be \(+2\), meaning this nitrogen is reduced (\(+4 \rightarrow +2\)). Because the same element starting at \(+4\) is simultaneously raised to \(+5\) and lowered to \(+2\), the reaction is a disproportionation. (Choice B) Oxygen stays at \(-2\) in every species here (\(\text{NO}_2\), \(\text{H}_2\text{O}\), \(\text{HNO}_3\), and \(\text{NO}\)), so it does not change oxidation state and is not the disproportionating element. (Choice C) Hydrogen is \(+1\) in both \(\text{H}_2\text{O}\) and \(\text{HNO}_3\); it does not change oxidation state and never reaches \(0\) in this reaction. (Choice D) Nitrogen does disproportionate, but the product states are wrong: nitrogen cannot exceed \(+5\) (its group maximum), so \(+6\) is impossible, and in \(\text{NO}\) nitrogen is \(+2\), not \(0\). Skill 1$ex49$,
    'easy', '4E', $cc49$Stoichiometry (GC)$cc49$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'misconception', $a49B$attributing the redox change to oxygen rather than the central nonmetal$a49B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a49C$attributing the redox change to hydrogen rather than the central nonmetal$a49C$ FROM q
UNION ALL SELECT id, 'D', 'scale_unit_error', $a49D$correct disproportionating element but impossible/incorrect product oxidation states (+6 and 0)$a49D$ FROM q;

-- Q3 [Disproportionation Reactions · medium · Skill 2 · 4E Stoichiometry (GC) · ans B] (g50)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Disproportionation Reactions',
    $qt50$Hydrogen peroxide decomposes according to the balanced equation \(2\,\text{H}_2\text{O}_2 \rightarrow 2\,\text{H}_2\text{O} + \text{O}_2\). This is a disproportionation reaction in which a single element is simultaneously oxidized and reduced. Considering the oxidation state of that element in the products, what are the two final oxidation states it reaches?$qt50$,
    $op50$[{"label":"A","text":"Oxygen goes to \\(-1\\) in \\(\\text{H}_2\\text{O}\\) and to \\(0\\) in \\(\\text{O}_2\\)"},{"label":"B","text":"Oxygen goes to \\(-2\\) in \\(\\text{H}_2\\text{O}\\) and to \\(0\\) in \\(\\text{O}_2\\)"},{"label":"C","text":"Oxygen goes to \\(0\\) in \\(\\text{H}_2\\text{O}\\) and to \\(+2\\) in \\(\\text{O}_2\\)"},{"label":"D","text":"Hydrogen goes to \\(0\\) in \\(\\text{H}_2\\text{O}\\) and to \\(+1\\) in \\(\\text{O}_2\\)"}]$op50$::jsonb,
    'B',
    $ex50$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is B because oxygen is the element that disproportionates. In the reactant \(\text{H}_2\text{O}_2\), each hydrogen is \(+1\), so the two oxygen atoms must sum to \(-2\), giving each oxygen an oxidation state of \(-1\) (the characteristic peroxide value). In the products, oxygen reaches two different states: in \(\text{H}_2\text{O}\), hydrogen is \(+1\) and oxygen is \(-2\) (oxygen is reduced, gaining one electron per atom); in \(\text{O}_2\), an element in its standard elemental form has an oxidation state of \(0\) (oxygen is oxidized, losing one electron per atom). Thus the disproportionating element, oxygen, splits from \(-1\) into final states of \(-2\) and \(0\). (Choice A) This keeps oxygen at \(-1\) in \(\text{H}_2\text{O}\), but in water hydrogen is \(+1\) and the single oxygen must balance the molecule to neutral, forcing oxygen to \(-2\), not \(-1\); it confuses the reactant peroxide value with the product value. (Choice C) This reverses the direction of electron transfer, assigning oxygen \(0\) in \(\text{H}_2\text{O}\) and \(+2\) in \(\text{O}_2\); in fact elemental \(\text{O}_2\) is \(0\) and oxygen in water is \(-2\), so both assignments are inverted. (Choice D) This misidentifies the disproportionating element as hydrogen; hydrogen remains \(+1\) throughout (it is \(+1\) in both \(\text{H}_2\text{O}_2\) and \(\text{H}_2\text{O}\)) and does not appear in \(\text{O}_2\) at all, so it is neither oxidized nor reduced. Skill 2$ex50$,
    'medium', '4E', $cc50$Stoichiometry (GC)$cc50$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a50A$Carries the reactant peroxide value (-1) into the water product instead of recomputing$a50A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a50C$Inverts which product is oxidized vs reduced, swapping the 0 and -2 assignments$a50C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a50D$Misidentifies hydrogen rather than oxygen as the disproportionating element$a50D$ FROM q;

-- Q4 [Disproportionation Reactions · medium · Skill 3 · 4E Stoichiometry (GC) · ans C] (g51)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Disproportionation Reactions',
    $qt51$A disproportionation reaction is a redox process in which a single element, starting in one oxidation state, is simultaneously oxidized and reduced. Which of the following balanced reactions is a true disproportionation?$qt51$,
    $op51$[{"label":"A","text":"\\(\\text{Zn}(s) + \\text{Cu}^{2+}(aq) \\rightarrow \\text{Zn}^{2+}(aq) + \\text{Cu}(s)\\)"},{"label":"B","text":"\\(\\text{AgNO}_3(aq) + \\text{NaCl}(aq) \\rightarrow \\text{AgCl}(s) + \\text{NaNO}_3(aq)\\)"},{"label":"C","text":"\\(3\\,\\text{MnO}_4^{2-} + 4\\,\\text{H}^+ \\rightarrow 2\\,\\text{MnO}_4^- + \\text{MnO}_2 + 2\\,\\text{H}_2\\text{O}\\)"},{"label":"D","text":"\\(\\text{HCl}(aq) + \\text{NaOH}(aq) \\rightarrow \\text{NaCl}(aq) + \\text{H}_2\\text{O}(l)\\)"}]$op51$::jsonb,
    'C',
    $ex51$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is C because manganese is the single element that is both oxidized and reduced. In the manganate reactant \(\text{MnO}_4^{2-}\), Mn is \(+6\) (Mn \(+ 4(-2) = -2\)). In one product it rises to \(+7\) in permanganate \(\text{MnO}_4^-\) (Mn \(+ 4(-2) = -1\)), meaning that manganese is oxidized; in the other product it falls to \(+4\) in \(\text{MnO}_2\) (Mn \(+ 2(-2) = 0\)), meaning that manganese is reduced. Because one element (Mn) leaves a single starting oxidation state (\(+6\)) and is simultaneously driven both up and down, this is a genuine disproportionation. (Choice A) This is an ordinary two-element redox: Zn is oxidized from \(0\) to \(+2\) while a different element, copper, is reduced from \(+2\) to \(0\); since two different elements undergo the oxidation-number changes, it is not a disproportionation. (Choice B) This is a double-displacement precipitation; Ag remains \(+1\), Na remains \(+1\), N remains \(+5\), Cl remains \(-1\), and O remains \(-2\), so no oxidation states change and there is no redox at all. (Choice D) This is an acid-base neutralization in which H stays \(+1\), O stays \(-2\), Na stays \(+1\), and Cl stays \(-1\); because no element changes oxidation number, it is neither a redox reaction nor a disproportionation. Skill 3$ex51$,
    'medium', '4E', $cc51$Stoichiometry (GC)$cc51$, 'general-chemistry', 3, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a51A$ordinary two-element redox mistaken for self-redox$a51A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a51B$non-redox double-displacement precipitation treated as disproportionation$a51B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a51D$acid-base neutralization with no oxidation-state change treated as disproportionation$a51D$ FROM q;

-- Q5 [Disproportionation Reactions · medium · Skill 2 · 4E Stoichiometry (GC) · ans D] (g52)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Disproportionation Reactions',
    $qt52$When hot concentrated base reacts with chlorine, hypochlorite ion disproportionates according to the balanced equation \(3\,\text{ClO}^- \rightarrow 2\,\text{Cl}^- + \text{ClO}_3^-\). In this self-redox process, chlorine begins in a single oxidation state in \(\text{ClO}^-\) and ends distributed between the two products. What are the two oxidation states that the disproportionating chlorine reaches in the products \(\text{Cl}^-\) and \(\text{ClO}_3^-\), respectively?$qt52$,
    $op52$[{"label":"A","text":"\\(+1\\) in \\(\\text{Cl}^-\\) and \\(+7\\) in \\(\\text{ClO}_3^-\\)"},{"label":"B","text":"\\(-1\\) in \\(\\text{Cl}^-\\) and \\(+3\\) in \\(\\text{ClO}_3^-\\)"},{"label":"C","text":"\\(0\\) in \\(\\text{Cl}^-\\) and \\(+5\\) in \\(\\text{ClO}_3^-\\)"},{"label":"D","text":"\\(-1\\) in \\(\\text{Cl}^-\\) and \\(+5\\) in \\(\\text{ClO}_3^-\\)"}]$op52$::jsonb,
    'D',
    $ex52$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is D because disproportionation requires the single starting element to split into one product where it is reduced and one where it is oxidized, and the oxidation-number bookkeeping fixes both values exactly. In the reactant \(\text{ClO}^-\), oxygen is assigned \(-2\), so chlorine must satisfy \((\text{Cl}) + (-2) = -1\), giving \(\text{Cl} = +1\). In \(\text{Cl}^-\) the ion charge is the oxidation number, so \(\text{Cl} = -1\) (chlorine is reduced, gaining 2 electrons per atom). In \(\text{ClO}_3^-\), the three oxygens contribute \(3\times(-2) = -6\), and the overall \(-1\) charge requires \((\text{Cl}) + (-6) = -1\), so \(\text{Cl} = +5\) (chlorine is oxidized, losing 4 electrons per atom). The electron ledger balances: the 2 chlorines reduced from \(+1\) to \(-1\) gain \(2\times2 = 4\) electrons, exactly matching the 1 chlorine oxidized from \(+1\) to \(+5\) that loses 4 electrons. Thus the disproportionating chlorine reaches \(-1\) and \(+5\). (Choice A) This reverses the direction of electron flow by claiming chlorine is oxidized to \(+1\) in \(\text{Cl}^-\) (the starting value) and pushed all the way to \(+7\) in \(\text{ClO}_3^-\); \(+7\) is the oxidation state in perchlorate \(\text{ClO}_4^-\), and \(\text{Cl}^-\) is the reduced product at \(-1\), not \(+1\). It treats both products as oxidized and overshoots the chlorate oxidation number (reversed_relationship). (Choice B) This keeps the correct \(-1\) for \(\text{Cl}^-\) but assigns \(+3\) to chlorine in \(\text{ClO}_3^-\); \(+3\) is the oxidation state of chlorine in chlorite \(\text{ClO}_2^-\), not chlorate. For \(\text{ClO}_3^-\) the three oxygens force \(\text{Cl} = +5\), so this misidentifies the oxyanion by confusing chlorate with chlorite (adjacent_fact). (Choice C) This assigns \(0\) to chlorine in \(\text{Cl}^-\), treating it as elemental \(\text{Cl}_2\); a monatomic ion's oxidation number equals its charge, so \(\text{Cl}^-\) is \(-1\), not \(0\). Reading the reduced product as oxidation state \(0\) understates the electron gain and breaks the electron balance with the \(+5\) product (process_step_confusion). Skill 2$ex52$,
    'medium', '4E', $cc52$Stoichiometry (GC)$cc52$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a52A$Both products read as oxidized; perchlorate +7 substituted and Cl- left at starting +1$a52A$ FROM q
UNION ALL SELECT id, 'B', 'adjacent_fact', $a52B$Chlorate confused with chlorite (assigns +3 from ClO2- to ClO3-)$a52B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a52C$Treats reduced Cl- as elemental oxidation state 0 instead of the ion charge -1$a52C$ FROM q;

-- Q6 [Disproportionation Reactions · hard · Skill 4 · 4E Stoichiometry (GC) · ans A] (g53)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Disproportionation Reactions',
    $qt53$When potassium chlorate is heated under controlled conditions, it can decompose without releasing oxygen gas according to the balanced equation \(4\,\text{KClO}_3 \rightarrow 3\,\text{KClO}_4 + \text{KCl}\). In the reactant, chlorine sits at an intermediate oxidation state. Which statement correctly classifies this reaction and identifies the oxidation states of chlorine in the two products?$qt53$,
    $op53$[{"label":"A","text":"It is a disproportionation reaction; chlorine is \\(+7\\) in \\(\\text{KClO}_4\\) and \\(-1\\) in \\(\\text{KCl}\\)."},{"label":"B","text":"It is a disproportionation reaction; chlorine is \\(+5\\) in \\(\\text{KClO}_4\\) and \\(+1\\) in \\(\\text{KCl}\\)."},{"label":"C","text":"It is a disproportionation reaction; chlorine is \\(-1\\) in \\(\\text{KClO}_4\\) and \\(+7\\) in \\(\\text{KCl}\\)."},{"label":"D","text":"It is a combination reaction; chlorine is \\(+7\\) in \\(\\text{KClO}_4\\) and \\(-1\\) in \\(\\text{KCl}\\)."}]$op53$::jsonb,
    'A',
    $ex53$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is A because chlorine begins at an intermediate oxidation state and ends up at both a higher and a lower state, which is the defining feature of disproportionation. Assign oxidation numbers using the standard rules: potassium is always \(+1\) and oxygen is \(-2\). In \(\text{KClO}_3\): \((+1) + \text{Cl} + 3(-2) = 0\), so \(\text{Cl} = +5\) (the intermediate state). In \(\text{KClO}_4\): \((+1) + \text{Cl} + 4(-2) = 0\), so \(\text{Cl} = +7\); chlorine is oxidized, losing 2 electrons per atom. In \(\text{KCl}\): \((+1) + \text{Cl} = 0\), so \(\text{Cl} = -1\); chlorine is reduced, gaining 6 electrons per atom. The same element (Cl) is therefore both oxidized (\(+5 \rightarrow +7\)) and reduced (\(+5 \rightarrow -1\)) in one reaction, confirming disproportionation. The electron bookkeeping balances: the 3 Cl atoms oxidized lose \(3 \times 2 = 6\) electrons, exactly matching the \(1 \times 6 = 6\) electrons gained by the single Cl atom reduced. (Choice B) misidentifies disproportionation but reports the wrong product states: chlorine in \(\text{KClO}_4\) is \(+7\) (not \(+5\), which would leave the perchlorate charge unbalanced at \(4(-2)+5 = -3\)), and chlorine in \(\text{KCl}\) is \(-1\) (not \(+1\)); these values also fail to bracket the \(+5\) starting state required for disproportionation. (Choice C) correctly calls the reaction disproportionation but reverses the assignments, placing the oxidized state \(+7\) on \(\text{KCl}\) and the reduced state \(-1\) on \(\text{KClO}_4\); in fact the oxygen-rich perchlorate ion forces the higher \(+7\) value while the bare chloride is \(-1\). (Choice D) gives the correct oxidation numbers but misclassifies the reaction: a single reactant breaking into two products is a decomposition, not a combination (which requires two or more reactants forming one product); because one element is simultaneously oxidized and reduced, the precise label is disproportionation. Skill 4$ex53$,
    'hard', '4E', $cc53$Stoichiometry (GC)$cc53$, 'general-chemistry', 4, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'process_step_confusion', $a53B$Correct disproportionation label but botched oxidation-number arithmetic for both products$a53B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a53C$Swaps which product holds the oxidized (+7) versus reduced (-1) chlorine$a53C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a53D$Right oxidation states but mislabels a single-reactant decomposition as combination$a53D$ FROM q;

-- Q7 [Net Ionic Equations & Spectator Ions · easy · Skill 1 · 4E Stoichiometry (GC) · ans B] (g54)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Net Ionic Equations & Spectator Ions',
    $qt54$When aqueous silver nitrate is combined with aqueous sodium chloride, a white precipitate of silver chloride forms according to \(\text{AgNO}_3(aq) + \text{NaCl}(aq) \rightarrow \text{AgCl}(s) + \text{NaNO}_3(aq)\). Which pair of ions remains dissolved and unchanged on both sides of the corresponding net ionic equation?$qt54$,
    $op54$[{"label":"A","text":"\\(\\text{Ag}^+\\) and \\(\\text{Cl}^-\\)"},{"label":"B","text":"\\(\\text{Na}^+\\) and \\(\\text{NO}_3^-\\)"},{"label":"C","text":"\\(\\text{Ag}^+\\) and \\(\\text{NO}_3^-\\)"},{"label":"D","text":"\\(\\text{Na}^+\\) and \\(\\text{Cl}^-\\)"}]$op54$::jsonb,
    'B',
    $ex54$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is B because spectator ions are the ions that appear in identical form on both the reactant and product sides of the complete ionic equation and so cancel out of the net ionic equation. Writing every soluble strong electrolyte as separated aqueous ions gives the complete ionic equation \(\text{Ag}^+(aq) + \text{NO}_3^-(aq) + \text{Na}^+(aq) + \text{Cl}^-(aq) \rightarrow \text{AgCl}(s) + \text{Na}^+(aq) + \text{NO}_3^-(aq)\). The solid \(\text{AgCl}\) stays written as a formula unit because it is insoluble, so \(\text{Ag}^+\) and \(\text{Cl}^-\) are consumed and do not survive on both sides. Crossing out the ions that appear unchanged on both sides removes \(\text{Na}^+(aq)\) and \(\text{NO}_3^-(aq)\), leaving the net ionic equation \(\text{Ag}^+(aq) + \text{Cl}^-(aq) \rightarrow \text{AgCl}(s)\). Because \(\text{Na}^+\) and \(\text{NO}_3^-\) are present unchanged on both sides, they are the spectator ions. (Choice A) \(\text{Ag}^+\) and \(\text{Cl}^-\) are the reacting ions that combine to form the \(\text{AgCl}(s)\) precipitate; they are the species that remain in the net ionic equation, the exact opposite of spectators. (Choice C) \(\text{NO}_3^-\) is indeed a spectator, but \(\text{Ag}^+\) is not, because \(\text{Ag}^+\) is incorporated into the insoluble \(\text{AgCl}\) and is removed from solution rather than left unchanged. (Choice D) \(\text{Na}^+\) is a genuine spectator, but \(\text{Cl}^-\) is not, because \(\text{Cl}^-\) is consumed into the \(\text{AgCl}(s)\) precipitate and therefore does not appear unchanged on both sides. Skill 1$ex54$,
    'easy', '4E', $cc54$Stoichiometry (GC)$cc54$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
