-- Q8 [Net Ionic Equations & Spectator Ions · easy · Skill 1 · 4E Stoichiometry (GC) · ans C] (g55)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Net Ionic Equations & Spectator Ions',
    $qt55$Equal volumes of aqueous potassium chloride, \(\text{KCl}\), and aqueous sodium nitrate, \(\text{NaNO}_3\), are combined in a beaker. Both salts are freely soluble, and the only conceivable exchange products, \(\text{KNO}_3\) and \(\text{NaCl}\), are themselves freely soluble strong electrolytes. Which statement best describes the net ionic equation for this mixture and the role of the dissolved ions?$qt55$,
    $op55$[{"label":"A","text":"A precipitate of \\(\\text{NaCl}\\) forms, so the net ionic equation is \\(\\text{Na}^+ + \\text{Cl}^- \\rightarrow \\text{NaCl}\\) and \\(\\text{K}^+\\) and \\(\\text{NO}_3^-\\) are the spectator ions."},{"label":"B","text":"Only \\(\\text{K}^+\\) and \\(\\text{Na}^+\\) are spectator ions, while \\(\\text{Cl}^-\\) and \\(\\text{NO}_3^-\\) combine, giving the net ionic equation \\(\\text{Cl}^- + \\text{NO}_3^- \\rightarrow \\text{ClNO}_3\\)."},{"label":"C","text":"All four ions, \\(\\text{K}^+\\), \\(\\text{Cl}^-\\), \\(\\text{Na}^+\\), and \\(\\text{NO}_3^-\\), are spectator ions, so no net ionic equation can be written because no net reaction occurs."},{"label":"D","text":"Spectator ions are the ions that combine to form the product, so \\(\\text{K}^+\\) and \\(\\text{NO}_3^-\\) react as the spectators while \\(\\text{Na}^+\\) and \\(\\text{Cl}^-\\) are left unchanged."}]$op55$::jsonb,
    'C',
    $ex55$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is C because a spectator ion is, by definition, an ion that appears unchanged on both sides of the complete ionic equation and is therefore dropped when writing the net ionic equation. In this mixture the complete ionic equation is \(\text{K}^+ + \text{Cl}^- + \text{Na}^+ + \text{NO}_3^- \rightarrow \text{K}^+ + \text{Cl}^- + \text{Na}^+ + \text{NO}_3^-\). Because every possible product (\(\text{KNO}_3\) and \(\text{NaCl}\)) is a soluble strong electrolyte, no precipitate, gas, or weak electrolyte forms, so there is no driving force to remove any ion from solution. Each of \(\text{K}^+\), \(\text{Cl}^-\), \(\text{Na}^+\), and \(\text{NO}_3^-\) appears identically on the left and right and cancels; with every ion canceling as a spectator, nothing remains, so no net ionic equation can be written and no net reaction occurs. (Choice A) This invokes a precipitate of \(\text{NaCl}\), but sodium salts and chloride salts are both soluble, so \(\text{NaCl}\) stays fully dissociated in water; no precipitate forms and \(\text{Na}^+ + \text{Cl}^- \rightarrow \text{NaCl}\) is not a valid net reaction here. (Choice B) This proposes that \(\text{Cl}^-\) and \(\text{NO}_3^-\) combine into a species "\(\text{ClNO}_3\)," but two anions do not bond to each other to form a neutral product; no such ionic exchange product exists, so these ions remain spectators in solution. (Choice D) This reverses the definition of a spectator ion: spectators are precisely the ions that do NOT participate in the net reaction, not the ions that combine to form a product. Calling the reacting pair the spectators inverts the meaning, and in any case no product forms here. Skill 1$ex55$,
    'easy', '4E', $cc55$Stoichiometry (GC)$cc55$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a55A$Assumes any double-displacement mixing yields a precipitate (treats soluble NaCl as insoluble)$a55A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a55B$Invents an anion-anion product (ClNO3) and forces a net reaction where none exists$a55B$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a55D$Reverses the definition of a spectator ion, calling the reacting ions the spectators$a55D$ FROM q;

-- Q9 [Net Ionic Equations & Spectator Ions · easy · Skill 1 · 4E Stoichiometry (GC) · ans D] (g56)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Net Ionic Equations & Spectator Ions',
    $qt56$When the complete ionic equation is written for the reaction of nitric acid with potassium hydroxide, \(\text{HNO}_3(aq) + \text{KOH}(aq) \rightarrow \text{KNO}_3(aq) + \text{H}_2\text{O}(l)\), some formulas are written as separated aqueous ions while others are kept together as a single chemical unit. Which species is correctly written as a single, intact unit rather than as separated ions?$qt56$,
    $op56$[{"label":"A","text":"\\(\\text{KNO}_3\\), because the salt formed in a neutralization is a precipitate that remains undissociated."},{"label":"B","text":"\\(\\text{HNO}_3\\), because it is a covalent molecule that stays intact in aqueous solution."},{"label":"C","text":"\\(\\text{KOH}\\), because the strong ionic bond between \\(\\text{K}^+\\) and \\(\\text{OH}^-\\) prevents it from separating in water."},{"label":"D","text":"\\(\\text{H}_2\\text{O}\\), because liquid water is a molecular species that does not appreciably dissociate."}]$op56$::jsonb,
    'D',
    $ex56$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is D because, in a complete ionic equation, only strong electrolytes are written as separated aqueous ions, while weak electrolytes and nonelectrolytes are kept together as a single unit. Nitric acid is a strong acid and potassium hydroxide is a strong base, so both dissociate completely and are written as \(\text{H}^+(aq) + \text{NO}_3^-(aq)\) and \(\text{K}^+(aq) + \text{OH}^-(aq)\), respectively; the product \(\text{KNO}_3\) is a soluble salt (a strong electrolyte) and is likewise written as \(\text{K}^+(aq) + \text{NO}_3^-(aq)\). Water, however, is a molecular liquid that ionizes only to a negligible extent, so it is a nonelectrolyte for this purpose and is kept together as the single unit \(\text{H}_2\text{O}(l)\). Thus the complete ionic equation is \(\text{H}^+ + \text{NO}_3^- + \text{K}^+ + \text{OH}^- \rightarrow \text{K}^+ + \text{NO}_3^- + \text{H}_2\text{O}\), where \(\text{K}^+\) and \(\text{NO}_3^-\) are the spectator ions that cancel, leaving the net ionic equation \(\text{H}^+ + \text{OH}^- \rightarrow \text{H}_2\text{O}\). (Choice A) \(\text{KNO}_3\) is a soluble (highly water-soluble) ionic salt, not a precipitate; because it is a strong electrolyte it is written as separated \(\text{K}^+(aq)\) and \(\text{NO}_3^-(aq)\) ions, which then act as spectators. (Choice B) \(\text{HNO}_3\) is a strong acid, not an intact covalent molecule in solution; it dissociates essentially completely into \(\text{H}^+(aq)\) and \(\text{NO}_3^-(aq)\) and must be written as separated ions. (Choice C) \(\text{KOH}\) is a strong base that dissolves and dissociates fully into \(\text{K}^+(aq)\) and \(\text{OH}^-(aq)\); a strong base in aqueous solution is written as separated ions, not as one unit. Skill 1$ex56$,
    'easy', '4E', $cc56$Stoichiometry (GC)$cc56$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a56A$soluble salt mistaken for precipitate$a56A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a56B$strong acid treated as intact molecule$a56B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a56C$strong base kept undissociated$a56C$ FROM q;

-- Q10 [Net Ionic Equations & Spectator Ions · medium · Skill 2 · 4E Stoichiometry (GC) · ans A] (g57)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Net Ionic Equations & Spectator Ions',
    $qt57$When aqueous barium chloride is mixed with aqueous sodium sulfate, a white precipitate forms according to \(\text{BaCl}_2(aq) + \text{Na}_2\text{SO}_4(aq) \rightarrow \text{BaSO}_4(s) + 2\,\text{NaCl}(aq)\). Which of the following is the balanced net ionic equation for this reaction?$qt57$,
    $op57$[{"label":"A","text":"\\(\\text{Ba}^{2+}(aq) + \\text{SO}_4^{2-}(aq) \\rightarrow \\text{BaSO}_4(s)\\)"},{"label":"B","text":"\\(\\text{Na}^+(aq) + \\text{Cl}^-(aq) \\rightarrow \\text{NaCl}(s)\\)"},{"label":"C","text":"\\(\\text{Ba}^{2+}(aq) + 2\\,\\text{Cl}^-(aq) + 2\\,\\text{Na}^+(aq) + \\text{SO}_4^{2-}(aq) \\rightarrow \\text{BaSO}_4(s) + 2\\,\\text{Na}^+(aq) + 2\\,\\text{Cl}^-(aq)\\)"},{"label":"D","text":"\\(\\text{Ba}^{2+}(aq) + 2\\,\\text{SO}_4^{2-}(aq) \\rightarrow \\text{BaSO}_4(s)\\)"}]$op57$::jsonb,
    'A',
    $ex57$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is A because the net ionic equation includes only the species that actually change during the reaction, after canceling the spectator ions. Writing every soluble strong electrolyte as separate ions gives the complete ionic equation \(\text{Ba}^{2+}(aq) + 2\,\text{Cl}^-(aq) + 2\,\text{Na}^+(aq) + \text{SO}_4^{2-}(aq) \rightarrow \text{BaSO}_4(s) + 2\,\text{Na}^+(aq) + 2\,\text{Cl}^-(aq)\). The \(\text{Na}^+\) and \(\text{Cl}^-\) ions appear unchanged on both sides, so they are spectator ions and cancel, leaving \(\text{Ba}^{2+}(aq) + \text{SO}_4^{2-}(aq) \rightarrow \text{BaSO}_4(s)\). This equation is balanced in mass (one Ba, one S, four O on each side) and in charge (\(+2\) and \(-2\) sum to \(0\) on the left, matching the neutral solid on the right), and it correctly uses a 1:1 ratio because each \(\text{Ba}^{2+}\) combines with one \(\text{SO}_4^{2-}\). (Choice B) This shows sodium and chloride combining into a solid, but NaCl is soluble and remains fully dissociated in solution; \(\text{Na}^+\) and \(\text{Cl}^-\) are the spectator ions that should be eliminated, not the species written into the net reaction. (Choice C) This is the complete (total) ionic equation written before any cancellation; it still contains the \(\text{Na}^+\) and \(\text{Cl}^-\) spectator ions that appear identically on both sides, so it has not been reduced to the net ionic form. (Choice D) This places a coefficient of 2 on the sulfate ion, but charge is not conserved (left side \(+2 + 2(-2) = -2\) does not equal the neutral right side) and the precipitate \(\text{BaSO}_4\) contains barium and sulfate in a 1:1 ratio, so only one \(\text{SO}_4^{2-}\) is consumed per \(\text{Ba}^{2+}\). Skill 2$ex57$,
    'medium', '4E', $cc57$Stoichiometry (GC)$cc57$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a57B$Treats the soluble spectator pair (Na+/Cl-) as the precipitate-forming ions and keeps the actual reactive ions as spectators$a57B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a57C$Stops at the complete ionic equation and never cancels the spectator ions to reach the net form$a57C$ FROM q
UNION ALL SELECT id, 'D', 'scale_unit_error', $a57D$Adds an incorrect coefficient of 2 to sulfate, breaking the 1:1 stoichiometry and charge balance$a57D$ FROM q;

-- Q11 [Net Ionic Equations & Spectator Ions · medium · Skill 2 · 4E Stoichiometry (GC) · ans B] (g58)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Oxidation-Reduction Reactions', 'Net Ionic Equations & Spectator Ions',
    $qt58$Hydrochloric acid is mixed with aqueous sodium hydroxide, and the reaction proceeds according to the balanced molecular equation \(\text{HCl}(aq) + \text{NaOH}(aq) \rightarrow \text{NaCl}(aq) + \text{H}_2\text{O}(l)\). Both HCl and NaOH are strong electrolytes that dissociate completely in water, and the NaCl product is fully soluble. Which equation correctly represents the net ionic equation for this neutralization?$qt58$,
    $op58$[{"label":"A","text":"\\(\\text{HCl}(aq) + \\text{NaOH}(aq) \\rightarrow \\text{NaCl}(aq) + \\text{H}_2\\text{O}(l)\\)"},{"label":"B","text":"\\(\\text{H}^+(aq) + \\text{OH}^-(aq) \\rightarrow \\text{H}_2\\text{O}(l)\\)"},{"label":"C","text":"\\(\\text{Na}^+(aq) + \\text{Cl}^-(aq) \\rightarrow \\text{NaCl}(aq)\\)"},{"label":"D","text":"\\(2\\,\\text{H}^+(aq) + 2\\,\\text{OH}^-(aq) \\rightarrow 2\\,\\text{H}_2\\text{O}(l)\\)"}]$op58$::jsonb,
    'B',
    $ex58$This is a General Chemistry question that falls under the content category 'Stoichiometry (GC)'. The answer to this question is B because the complete ionic equation, obtained by writing every strong electrolyte as its dissociated ions, is \(\text{H}^+(aq) + \text{Cl}^-(aq) + \text{Na}^+(aq) + \text{OH}^-(aq) \rightarrow \text{Na}^+(aq) + \text{Cl}^-(aq) + \text{H}_2\text{O}(l)\). Both \(\text{Na}^+\) and \(\text{Cl}^-\) appear unchanged on both sides of the arrow, so they are spectator ions and are cancelled. Removing them leaves \(\text{H}^+(aq) + \text{OH}^-(aq) \rightarrow \text{H}_2\text{O}(l)\), the net ionic equation for any strong-acid/strong-base neutralization, written in the lowest whole-number coefficients. (Choice A) This is the molecular (formula-unit) equation, not the net ionic equation; it leaves the strong electrolytes undissociated and therefore retains the spectator ions \(\text{Na}^+\) and \(\text{Cl}^-\) instead of cancelling them. (Choice C) This combines the two spectator ions into the soluble salt; \(\text{Na}^+\) and \(\text{Cl}^-\) do not react and remain dissolved as ions, so this reverses the analysis by treating the spectators as the reacting species and discarding the actual reaction between \(\text{H}^+\) and \(\text{OH}^-\). (Choice D) The species and the chemistry are correct, but the coefficients are not reduced to the lowest whole-number ratio; a net ionic equation must be expressed with the smallest integer coefficients, which here is the 1:1:1 form. Skill 2$ex58$,
    'medium', '4E', $cc58$Stoichiometry (GC)$cc58$, 'general-chemistry', 2, 110
  ) RETURNING id
)
